/**
 * Golden expectations produced by the Python engine's ffmpeg 7.1 binary (the oracle of the audio spike), generated
 * by scratchpad m3-audio/make-golden.mjs. Only ffmpeg's OUTPUT is stored (base64 Float32); the inputs are rebuilt by
 * the generator functions below, which must stay identical to the script. Do not edit by hand.
 */

export function goldenNoise(n: number, seed = 1, amp = 0.3): Float32Array {
  const x = new Float32Array(n);
  let s = seed >>> 0;
  for (let i = 0; i < n; i++) {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    x[i] = ((s >>> 8) / 16777216 - 0.5) * 2 * amp;
  }
  return x;
}

export function goldenSine(n: number, rate: number, hz: number, amp = 0.5): Float32Array {
  const x = new Float32Array(n);
  for (let i = 0; i < n; i++) x[i] = amp * Math.sin((2 * Math.PI * hz * i) / rate);
  return x;
}

export function goldenConcat(parts: Float32Array[]): Float32Array {
  const out = new Float32Array(parts.reduce((a, p) => a + p.length, 0));
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
}

/** Resampler input: a third noise, a third 1 kHz tone, a third quiet noise, at `rate`. */
export function resamplerGoldenInput(rate: number, seconds: number): Float32Array {
  const n = Math.round(rate * seconds);
  const third = Math.floor(n / 3);
  return goldenConcat([
    goldenNoise(third, 5, 0.2),
    goldenSine(third, rate, 1000, 0.5),
    goldenNoise(n - 2 * third, 11, 0.02),
  ]);
}

/** Clean-up input (int16 values): level changes so dynaudnorm has work, 0.4 s of digital silence, a 440 Hz tone. */
export function cleanupGoldenInputInt16(rate: number, seconds: number): Float32Array {
  const n = Math.round(rate * seconds);
  const x = new Float32Array(n);
  const nz = goldenNoise(n, 21, 1);
  for (let i = 0; i < n; i++) {
    const t = i / rate;
    const burst = t < 1.0 ? 0.05 : t < 1.6 ? 0.4 : t < 2.0 ? 0 : t < 3.0 ? 0.15 : 0.6;
    const env = 0.5 + 0.5 * Math.sin(2 * Math.PI * 0.7 * t);
    const v =
      burst * env * nz[i] +
      0.1 * burst * Math.sin(2 * Math.PI * 440 * t) +
      (t > 3.5 ? 0.02 * Math.sin(2 * Math.PI * 7000 * t) : 0);
    x[i] = Math.max(-32768, Math.min(32767, Math.round(v * 32767)));
  }
  return x;
}

export function decodeGolden(b64: string): Float32Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Float32Array(bytes.buffer);
}

